static int atmtcp_recv_control(const struct atmtcp_control *msg,
			       struct atm_dev *dev)
{
	struct atm_vcc *vcc = *(struct atm_vcc **) &msg->vcc;
	struct atm_vcc *walk_vcc;
	struct hlist_head *head;
	struct sock *s;
	int i;
	int matches = 0;

	read_lock(&vcc_sklist_lock);
	for(i = 0; i < VCC_HTABLE_SIZE; ++i) {
		head = &vcc_hash[i];
		sk_for_each(s, head) {
			walk_vcc = atm_sk(s);
			if (walk_vcc->dev != dev)
				continue;
			if (walk_vcc == vcc) {
				sock_hold(s);
				matches = 1;
				break;
			}
		}
		if (matches)
			break;
	}
	read_unlock(&vcc_sklist_lock);
	if (!matches)
		return -EUNATCH;

	vcc->vpi = msg->addr.sap_addr.vpi;
	vcc->vci = msg->addr.sap_addr.vci;
	vcc->qos = msg->qos;
	sk_atm(vcc)->sk_err = -msg->result;
	switch (msg->type) {
	    case ATMTCP_CTRL_OPEN:
		change_bit(ATM_VF_READY,&vcc->flags);
		break;
	    case ATMTCP_CTRL_CLOSE:
		change_bit(ATM_VF_ADDR,&vcc->flags);
		break;
	    default:
		printk(KERN_ERR "atmtcp_recv_control: unknown type %d\n",
		    msg->type);
		sock_put(sk_atm(vcc));
		return -EINVAL;
	}
	wake_up(sk_sleep(sk_atm(vcc)));
	sock_put(sk_atm(vcc));
	return 0;
}

